solutionCode:
public static class HighlightAllMatches
{
    public static int HighlightAllMatches(int[] scores, int[] weights)
    {
        var total = 0;
        var weightTotal = 0;
        for (var index = 0; index < scores.Length; index++)
        {
            total += scores[index] * weights[index];
            weightTotal += weights[index];
        }
        return total / weightTotal;
    }
}
